    for r in recs:
        c = r.get("message",{}).get("content")
        if not isinstance(c, list): continue
        for p in c:
            if not isinstance(p, dict): continue
            if p.get("type")=="tool_use":
                tools[p["name"]] += 1
                if p["name"]=="Bash":
                    cmd = p["input"].get("command","")
                    for m in re.finditer(r"git(?:\s+-C\s+\S+)*\s+show\s+(\S+)", cmd):
                        if ":" in m.group(1) and not m.group(1).startswith("-"): showfile += 1
                        else: showrev += 1
                    graph += len(re.findall(r"\bentire\s+graph\b", cmd))
                    why += len(re.findall(r"\bentire\s+why\b", cmd))
                    blame += len(re.findall(r"\bentire\s+blame\b", cmd))
                    if re.search(r"\bentire\s+search\b", cmd): search_ids[p["id"]] = cmd
            elif p.get("type")=="tool_result" and p.get("tool_use_id") in search_ids:
                out = p.get("content")
                if isinstance(out, list): out = " ".join(x.get("text","") for x in out if isinstance(x, dict))
                results[p["tool_use_id"]] = (out or "")[:300].replace("\n"," | ")
    print(f"#{pr} tools={dict(tools.most_common(8))}")
    print(f"     git show path@rev={showfile} git show commit={showrev} entire graph={graph} why={why} blame={blame}")
    for k,v in results.items(): print("     entire search ->", v)
    tot.update(tools)
print("TOTAL tools", dict(tot.most_common(10)))
EOF
